CREATE TABLE IF NOT EXISTS sessions (session_id VARCHAR(128) COLLATE utf8mb4_bin PRIMARY KEY, expires BIGINT UNSIGNED NOT NULL, data MEDIUMTEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX sessions_expiration (expires));
CREATE TABLE IF NOT EXISTS admins (id INT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS room_types (id INT PRIMARY KEY AUTO_INCREMENT, slug VARCHAR(120) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, description TEXT NOT NULL, capacity INT UNSIGNED NULL, price_fcfa BIGINT UNSIGNED NULL, conditions_text TEXT, status ENUM('draft','published') DEFAULT 'draft', validated BOOLEAN DEFAULT FALSE, is_demo BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS amenities (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS room_type_amenities (room_type_id INT NOT NULL, amenity_id INT NOT NULL, PRIMARY KEY(room_type_id,amenity_id), FOREIGN KEY(room_type_id) REFERENCES room_types(id) ON DELETE CASCADE, FOREIGN KEY(amenity_id) REFERENCES amenities(id) ON DELETE CASCADE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS media (id INT PRIMARY KEY AUTO_INCREMENT, url VARCHAR(500) NOT NULL, alt VARCHAR(250) NOT NULL, category VARCHAR(100) NOT NULL, status ENUM('draft','published') DEFAULT 'draft', validated BOOLEAN DEFAULT FALSE, is_demo BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS room_type_media (room_type_id INT NOT NULL, media_id INT NOT NULL, PRIMARY KEY(room_type_id,media_id), FOREIGN KEY(room_type_id) REFERENCES room_types(id) ON DELETE CASCADE, FOREIGN KEY(media_id) REFERENCES media(id) ON DELETE CASCADE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS page_contents (id INT PRIMARY KEY AUTO_INCREMENT, slug VARCHAR(120) NOT NULL UNIQUE, title VARCHAR(200) NOT NULL, body TEXT NOT NULL, status ENUM('draft','published') DEFAULT 'draft', validated BOOLEAN DEFAULT FALSE, is_demo BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hotel_settings (id INT PRIMARY KEY AUTO_INCREMENT, setting_key VARCHAR(100) NOT NULL UNIQUE, value TEXT NOT NULL, validated BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reservation_requests (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) NOT NULL, email VARCHAR(254) NOT NULL, phone VARCHAR(40) NOT NULL, arrival DATE NOT NULL, departure DATE NOT NULL, adults INT UNSIGNED NOT NULL, children INT UNSIGNED NOT NULL DEFAULT 0, room_type_id INT NULL, message TEXT, consent BOOLEAN NOT NULL, status ENUM('pending','processing','confirmed','declined','cancelled') DEFAULT 'pending', internal_notes TEXT, notification_status ENUM('pending','sent','failed','unconfigured') DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(room_type_id) REFERENCES room_types(id) ON DELETE SET NULL, CHECK(departure > arrival), CHECK(adults >= 1));
CREATE TABLE IF NOT EXISTS event_requests (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) NOT NULL, email VARCHAR(254) NOT NULL, phone VARCHAR(40) NOT NULL, event_type VARCHAR(100) NOT NULL, event_date DATE NOT NULL, participants INT UNSIGNED NOT NULL, message TEXT NOT NULL, consent BOOLEAN NOT NULL, status ENUM('pending','processing','confirmed','declined','cancelled') DEFAULT 'pending', internal_notes TEXT, notification_status ENUM('pending','sent','failed','unconfigured') DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contact_messages (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) NOT NULL, email VARCHAR(254) NOT NULL, subject VARCHAR(200) NOT NULL, message TEXT NOT NULL, consent BOOLEAN NOT NULL, status ENUM('pending','processing','confirmed','declined','cancelled') DEFAULT 'pending', internal_notes TEXT, notification_status ENUM('pending','sent','failed','unconfigured') DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
